void parse_pdf_object(struct pdf_struct *pdf, struct pdf_obj *obj) {
    if (!pdf || !obj) {
        return;
    }

    if (obj->size <= 0) {
        return;
    }

    size_t dict_start = 0;
    size_t dict_end = 0;

    // Logic to find the start and end of the dictionary
    for (size_t i = 0; i < obj->size; ++i) {
        if (pdf->data[i] == '{') {
            dict_start = i + 1;
            break;
        }
    }

    for (size_t i = obj->size - 1; i > dict_start; --i) {
        if (pdf->data[i] == '}') {
            dict_end = i;
            break;
        }
    }

    if (dict_start >= dict_end) {
        return;
    }

    for (size_t i = dict_start; i < dict_end; ++i) {
        if (pdf->data[i] == '/') {
            size_t key_start = i + 1;
            size_t key_end = key_start;

            while (key_end < dict_end && pdf->data[key_end] != ' ' && pdf->data[key_end] != '\t' && pdf->data[key_end] != '/') {
                ++key_end;
            }

            std::string key(pdf->data + key_start, key_end - key_start);

            // Example logic for special cases
            if (key == "Linearized") {
                obj->flags.linearized = true;
            } else if (key == "Launch") {
                obj->flags.has_launch = true;
            } else if (key == "JS") {
                obj->flags.has_js = true;
            } else if (key == "F") {
                obj->flags.has_filter = true;
            }
        }
    }

    // Log debug information
    std::cout << "Parsed PDF object. Flags: Linearized=" << obj->flags.linearized
              << ", Launch=" << obj->flags.has_launch << ", JS=" << obj->flags.has_js
              << ", Filter=" << obj->flags.has_filter << std::endl;
}

void parse_pdf_object(struct pdf_struct *pdf, struct pdf_obj *obj) {
    // Initialize necessary variables
    char *dict_start = nullptr;
    char *dict_end = nullptr;
    char *current_pos = nullptr;
    int obj_size = 0;

    // Check the size of the object
    obj_size = get_object_size(pdf, obj);
    if (obj_size <= 0) {
        log_debug("Invalid object size for parsing.");
        return;
    }

    // Locate the start and end of the object's dictionary
    dict_start = find_dict_start(pdf, obj);
    if (!dict_start) {
        log_debug("Failed to locate dictionary start.");
        return;
    }

    dict_end = find_dict_end(pdf, obj);
    if (!dict_end) {
        log_debug("Failed to locate dictionary end.");
        return;
    }

    log_debug("Dictionary located from %p to %p", dict_start, dict_end);

    // Process PDF names within the dictionary
    current_pos = dict_start;
    while (current_pos < dict_end) {
        char *name = extract_pdf_name(pdf, current_pos);
        if (!name) {
            log_debug("Failed to extract PDF name.");
            break;
        }

        // Handle special cases for linearized PDFs
        if (strcmp(name, "Linearized") == 0) {
            handle_linearized_pdf(pdf, obj, current_pos);
            log_debug("Linearized PDF processing completed.");
        }

        // Handle launch actions
        else if (strcmp(name, "Launch") == 0) {
            handle_launch_action(pdf, obj, current_pos);
            log_debug("Launch action processing completed.");
        }

        // Handle JavaScript references
        else if (strcmp(name, "JavaScript") == 0) {
            handle_javascript_reference(pdf, obj, current_pos);
            log_debug("JavaScript reference processing completed.");
        }

        // Check for the presence of filters and update the object's flags accordingly
        else if (strcmp(name, "Filter") == 0) {
            handle_filters(pdf, obj, current_pos);
            log_debug("Filter processing completed.");
        }

        current_pos = next_element(pdf, current_pos);
    }

    log_debug("PDF object parsing completed.");
}

void parse_pdf_object(struct pdf_struct *pdf, struct pdf_obj *obj) {
    if (!pdf || !obj) {
        return;
    }

    // Initialize necessary variables
    size_t obj_size = obj->size;
    char *dict_start = nullptr;
    char *dict_end = nullptr;

    if (obj_size == 0) {
        fprintf(stderr, "Object size is zero, nothing to parse.\n");
        return;
    }

    // Locate the start and end of the object's dictionary
    dict_start = obj->data;
    dict_end = obj->data + obj_size;

    // Begin processing the dictionary content
    char *current = dict_start;
    while (current < dict_end) {
        // Example logic for finding and processing PDF names
        if (strncmp(current, "/Linearized", 11) == 0) {
            obj->flags.linearized = 1;
            fprintf(stderr, "Detected a linearized PDF.\n");
            current += 11;
        } else if (strncmp(current, "/Launch", 7) == 0) {
            obj->flags.launch_action = 1;
            fprintf(stderr, "Detected a launch action.\n");
            current += 7;
        } else if (strncmp(current, "/JS", 3) == 0) {
            obj->flags.has_js = 1;
            fprintf(stderr, "Detected JavaScript reference.\n");
            current += 3;
        } else if (strncmp(current, "/Filter", 7) == 0) {
            obj->flags.has_filter = 1;
            fprintf(stderr, "Detected a filter in the object.\n");
            current += 7;
        } else {
            // Skip to the next word or character
            current++;
        }
    }

    // Log final parsing status
    fprintf(stderr, "Finished parsing PDF object.\n");
}
